// ===== eingebettet aus src/freigabe.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const freigabe = (() => {
const module = { exports: {} };
// Freigabe Variante B (Bauplan 6): einmaliges, ablaufendes Token je Freigeber. Gespeichert wird nur der
// SHA-256-Hash. Der Endpunkt EPA-07 zeigt ein Formular (Vorschau, Text bearbeitbar, Senden/Ablehnen) und
// verbraucht die Freigabe atomar (bedingtes Update auf status = 'offen').

const TOKEN_MUSTER = /^[A-Za-z0-9_-]{43}$/; // 32 Byte base64url
const AKTIONEN = ['senden', 'ablehnen'];
// Freigabe im Teams-Kanal "Rückfragen": ein Link für alle Freigeber statt je einer pro Person. Wer entscheidet,
// wählt seinen Namen auf der Freigabe-Seite; nur Adressen aus der Freigeber-Liste sind erlaubt.
const KANAL = 'kanal';

/** Für wen Links erzeugt werden: ein Kanal-Link, sobald der Kanal "Rückfragen" eingerichtet ist, sonst je Freigeber. */
function linkEmpfaenger(config) {
	const k = config && config.kanaele;
	return k && k.rueckfragen ? [KANAL] : (config.freigeber || []);
}

/** Darf der Inhaber dieses Links überhaupt entscheiden? (vor der Anzeige) */
function freigeberErlaubt(tokenFreigeber, liste) {
	const l = (liste || []).map((s) => String(s).toLowerCase());
	if (String(tokenFreigeber || '') === KANAL) return l.length > 0;
	return l.includes(String(tokenFreigeber || '').toLowerCase());
}

/**
 * Wer entscheidet (für Protokoll und Status). Kanal-Link: die gewählte Adresse muss in der Freigeber-Liste stehen.
 * @returns {{ ok: true, entscheider: string } | { ok: false, meldung: string }}
 */
function entscheiderBestimmen(tokenFreigeber, liste, wer) {
	const l = (liste || []).map((s) => String(s).toLowerCase());
	if (String(tokenFreigeber || '') !== KANAL) return { ok: true, entscheider: String(tokenFreigeber || '').toLowerCase() };
	const w = String(wer || '').trim().toLowerCase();
	if (!w) return { ok: false, meldung: 'Bitte wählen Sie Ihren Namen aus.' };
	if (!l.includes(w)) return { ok: false, meldung: 'Sie sind für diesen Kunden nicht als Freigeber eingetragen.' };
	return { ok: true, entscheider: w };
}

/** @param {object} c Node-Modul "crypto" (im Code-Node per require('crypto')) */
function tokenErzeugen(c) {
	const token = c.randomBytes(32).toString('base64url');
	return { token, hash: tokenHash(c, token) };
}

function tokenHash(c, token) {
	return c.createHash('sha256').update(String(token), 'utf8').digest('hex');
}

function freigabeIdErzeugen(c) {
	return 'F-' + c.randomUUID();
}

function istGueltigesToken(t) {
	return typeof t === 'string' && TOKEN_MUSTER.test(t);
}

/** Basis-URL der Instanz aus $execution.resumeUrl (…/webhook-waiting/<id>) bzw. einem Override. */
function basisUrl(resumeUrl, override) {
	if (override) return String(override).replace(/\/+$/, '');
	const m = String(resumeUrl || '').match(/^(https?:\/\/[^/]+(?:\/[^/]+)*?)\/webhook-waiting\//);
	if (!m) throw new Error('Basis-URL der Instanz nicht ermittelbar');
	return m[1];
}

function link(basis, token) {
	return `${basis}/webhook/epa-freigabe?t=${encodeURIComponent(token)}`;
}

/**
 * Prüft Token und Freigabe vor Anzeige bzw. Entscheidung.
 * @returns {{ ok: true } | { ok: false, status: number, code: string, meldung: string }}
 */
function freigabePruefen({ token, freigabe, freigeberErlaubt, jetzt }) {
	const nein = (status, code, meldung) => ({ ok: false, status, code, meldung });
	if (!token || token.id === undefined) return nein(404, 'NICHT_GEFUNDEN', 'Dieser Freigabe-Link ist ungültig.');
	if (!freigabe || freigabe.id === undefined) return nein(404, 'NICHT_GEFUNDEN', 'Die Freigabe existiert nicht mehr.');
	if (freigabe.status !== 'offen') {
		const wer = freigabe.entscheider ? ` von ${freigabe.entscheider}` : '';
		const was = { in_versand: 'wird gerade versendet', gesendet: 'wurde bereits freigegeben und gesendet', abgelehnt: 'wurde bereits abgelehnt', abgelaufen: 'ist abgelaufen', ersetzt: 'wurde durch eine neuere Freigabe ersetzt', fehler: 'ist beim Versand fehlgeschlagen', unzustellbar: 'wurde gesendet, kam beim Kunden aber nicht an', nicht_zugestellt: 'wurde gesendet, kam beim Kunden aber nicht an' }[freigabe.status] || `hat den Status "${freigabe.status}"`;
		// Betreff nennen, damit klar ist, um welche Anfrage es geht (mehrere Links in einem Chat).
		const betrifft = freigabe.betreff ? ` Betrifft: ${String(freigabe.betreff).slice(0, 150)}` : '';
		return nein(freigabe.status === 'abgelaufen' ? 410 : 409, freigabe.status === 'abgelaufen' ? 'FREIGABE_ABGELAUFEN' : 'DUPLIKAT', `Diese ${freigabe.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage'} ${was}${freigabe.status === 'gesendet' || freigabe.status === 'abgelehnt' ? wer : ''}.${betrifft}`);
	}
	if (token.verbraucht_am) return nein(409, 'DUPLIKAT', 'Dieser Link wurde bereits verwendet.');
	if (new Date(freigabe.ablauf).getTime() <= new Date(jetzt).getTime()) return nein(410, 'FREIGABE_ABGELAUFEN', 'Dieser Freigabe-Link ist abgelaufen. Ein neuer Link wird automatisch verschickt.');
	// Ab M5: Links haben eine eigene Ablaufzeit. Bei der Erneuerung einer abgelaufenen Freigabe werden alle alten Links gesperrt.
	if (token.ablauf && new Date(token.ablauf).getTime() <= new Date(jetzt).getTime()) return nein(410, 'FREIGABE_ABGELAUFEN', 'Dieser Freigabe-Link ist abgelaufen. Sie haben inzwischen einen neuen Link erhalten.');
	if (!freigeberErlaubt) return nein(403, 'KEINE_BERECHTIGUNG', 'Sie sind für diesen Kunden nicht (mehr) als Freigeber eingetragen.');
	return { ok: true };
}

/** Formulardaten aus EPA-07 (POST, application/x-www-form-urlencoded). */
function formularLesen(body) {
	const b = body && typeof body === 'object' ? body : {};
	const aktion = String(b.aktion || '');
	if (!AKTIONEN.includes(aktion)) return { ok: false, meldung: 'Unbekannte Aktion.' };
	if (!istGueltigesToken(b.t)) return { ok: false, meldung: 'Ungültiger Link.' };
	const grund = String(b.grund || '').trim().slice(0, 500);
	if (aktion === 'ablehnen' && !grund) return { ok: false, meldung: 'Bitte einen Grund für die Ablehnung angeben.' };
	return { ok: true, aktion, token: b.t, text: typeof b.text === 'string' ? b.text : '', grund, wer: String(b.wer || '').trim().toLowerCase().slice(0, 200) };
}

function istBearbeitet(original, neu) {
	const n = (s) => String(s ?? '').replace(/\r\n?/g, '\n').replace(/[ \t]+/g, ' ').replace(/\s+$/gm, '').trim();
	return n(original) !== n(neu);
}

// ---------------------------------------------------------------- HTML

function esc(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

const STIL = `body{font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;margin:0;background:#f4f5f7;color:#1d2433}
main{max-width:760px;margin:0 auto;padding:16px}
.karte{background:#fff;border-radius:8px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.08);margin-bottom:16px}
h1{font-size:1.3rem;margin:0 0 12px}dl{display:grid;grid-template-columns:max-content 1fr;gap:4px 12px;margin:0}
dt{color:#5b6475}dd{margin:0;overflow-wrap:anywhere}textarea{width:100%;box-sizing:border-box;min-height:260px;font:inherit;padding:8px}
pre{white-space:pre-wrap;font:inherit;color:#5b6475;margin:8px 0 0}.knoepfe{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
button{font:inherit;padding:10px 16px;border-radius:6px;border:0;cursor:pointer}.senden{background:#1f6f43;color:#fff}.ablehnen{background:#a3222b;color:#fff}
input[type=text],select{width:100%;box-sizing:border-box;font:inherit;padding:8px}.hinweis{color:#5b6475;font-size:.9rem}
.ok{border-left:4px solid #1f6f43}.fehler{border-left:4px solid #a3222b}`;

function seite(titel, inhalt) {
	return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(titel)}</title><style>${STIL}</style></head><body><main>${inhalt}</main></body></html>`;
}

function seiteFormular({ token, freigabe, vorgang, fehlende, text, abschluss, auswahl }) {
	const luecken = (fehlende || []).map((f) => `<li>${esc(f.anzeigename)}${f.grund ? ` <span class="hinweis">(${esc(f.grund)})</span>` : ''}</li>`).join('');
	const was = freigabe.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage';
	return seite(`${was} ${vorgang.vorgangs_id}`, `
<div class="karte"><h1>${was} freigeben – ${esc(vorgang.vorgangs_id)}</h1>
<dl><dt>An</dt><dd>${esc(freigabe.empfaenger)}</dd><dt>Betreff</dt><dd>${esc(freigabe.betreff)}</dd>
<dt>Runde</dt><dd>${esc(Number(vorgang.rundenzaehler || 0) + 1)}</dd><dt>Gültig bis</dt><dd>${esc(new Date(freigabe.ablauf).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }))}</dd></dl>
<p>Fehlende Angaben:</p><ul>${luecken}</ul>${freigabe.fallback ? '<p class="hinweis">Hinweis: Die KI-Formulierung hat die Prüfung nicht bestanden, es wird die Standardvorlage verwendet.</p>' : ''}</div>
<form class="karte" method="post" onsubmit="var f=this;setTimeout(function(){var b=f.querySelectorAll('button');for(var i=0;i<b.length;i++)b[i].disabled=true},0)">
<input type="hidden" name="t" value="${esc(token)}">
${Array.isArray(auswahl) && auswahl.length ? `<label for="wer"><b>Wer entscheidet?</b></label><select id="wer" name="wer" required><option value="">Bitte Namen wählen …</option>${auswahl.map((a) => `<option value="${esc(a)}">${esc(a)}</option>`).join('')}</select><p class="hinweis">Ihr Name wird im Protokoll gespeichert.</p>` : ''}
<label for="text"><b>Text der Mail</b> (bearbeitbar)</label>
<textarea id="text" name="text">${esc(text)}</textarea>
<pre>${esc(abschluss)}</pre>
<p class="hinweis">Signatur und KI-Hinweis werden immer automatisch angehängt.</p>
<label for="grund">Grund (nur bei Ablehnung)</label><input type="text" id="grund" name="grund" maxlength="500">
<div class="knoepfe"><button class="senden" name="aktion" value="senden">Freigeben und senden</button>
<button class="ablehnen" name="aktion" value="ablehnen">Ablehnen (manuell bearbeiten)</button></div>
<p class="hinweis">Der Link ist nur einmal verwendbar. Nichts wird ohne Ihren Klick versendet.</p></form>`);
}

function seiteMeldung(titel, text, art = 'ok') {
	return seite(titel, `<div class="karte ${art === 'ok' ? 'ok' : 'fehler'}"><h1>${esc(titel)}</h1><p>${esc(text)}</p></div>`);
}

/** Teams-Nachricht an den Freigeber (1:1-Chat). */
const ANLASS = Object.freeze({
	freigabe_erinnerung: 'Erinnerung: Diese Freigabe ist noch offen. Hier ist ein neuer Link.',
	freigabe_erneuern: 'Der bisherige Link ist abgelaufen und gilt nicht mehr. Hier ist ein neuer Link.',
	freigabe_nach_fehler: 'Diese Nachricht wurde wegen eines Fehlers NICHT gesendet. Das Postfach ist wieder erreichbar, bitte erneut freigeben. Die bisherigen Links gelten nicht mehr.',
	freigabe_eskalation: 'Bitte jetzt entscheiden: freigeben, bearbeiten oder ablehnen. Hier ist ein neuer Link; alle bisherigen Links gelten nicht mehr.',
	freigabe_nach_unzustellbar: 'Der Zustelltest war wieder erfolgreich, der Versand funktioniert. Bitte prüfen und erneut freigeben; gesendet wird eine neue Mail mit demselben Text.',
});

/**
 * Nachricht an einen Freigeber. kontext_html (optional, vom Aufrufer erzeugt, bereits escaped) ist die Übersicht
 * zur Mail (erkannte und fehlende Angaben, Warnhinweise). Dann ersetzt diese eine Nachricht die sonst zusätzliche
 * Eingangsmeldung, und die Liste der fehlenden Angaben steht nicht doppelt drin.
 */
function nachrichtFreigeber({ vorgang, freigabe, fehlende, link: url, ablaufText, art, anlass, kontext_html: kontext, wartet_stunden: wartet, kanal }) {
	const liste = (fehlende || []).map((f) => `• ${esc(f.anzeigename)}`).join('<br>');
	const was = art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage';
	let hinweis = ANLASS[anlass] ? `<i>${esc(ANLASS[anlass])}</i><br>` : '';
	if (anlass === 'freigabe_nach_fehler') {
		hinweis = `<b>🔁 Erneut zur Freigabe: Versand war fehlgeschlagen</b><br>${freigabe.grund ? `Grund: ${esc(freigabe.grund)}<br>` : ''}${hinweis}<br>`;
	} else if (anlass === 'freigabe_eskalation') {
		const dauer = Number.isFinite(Number(wartet)) && wartet !== null ? `seit ${Number(wartet)} Stunden` : 'seit längerer Zeit';
		hinweis = `<b>⏰ Eskalation: Diese Freigabe wartet ${esc(dauer)}</b><br>Der Kunde hat noch keine Antwort bekommen.<br>${hinweis}<br>`;
	} else if (anlass === 'freigabe_nach_unzustellbar') {
		// freigabe.grund trägt hier den Grund der vorigen (nicht zugestellten) Freigabe.
		hinweis = `<b>🔁 Erneut zur Freigabe: Die Nachricht kam beim Kunden nicht an</b><br>${freigabe.grund ? `${esc(freigabe.grund)}<br>` : ''}${hinweis}<br>`;
	}
	const link = `<a href="${esc(url)}">Entwurf ansehen, bearbeiten oder freigeben</a><br><i>${kanal
		? `Der Link ist einmal verwendbar und gültig bis ${esc(ablaufText)}. Beim Öffnen wählen Sie Ihren Namen; er wird im Protokoll gespeichert.`
		: `Dieser persönliche Link ist einmal verwendbar und gültig bis ${esc(ablaufText)}. Bitte nicht weiterleiten.`}</i>`;
	const empfang = `An: ${esc(freigabe.empfaenger)}<br>Betreff: ${esc(freigabe.betreff)}<br><br>`;
	if (kontext && typeof kontext === 'string' && kontext.trim()) {
		return `${hinweis}${kontext}<br><br><b>${was} an den Kunden wurde erstellt</b><br>${empfang}${link}`;
	}
	return `${hinweis}<b>${was} an den Kunden freigeben</b><br><br>Vorgangsnummer: <b>${esc(vorgang.vorgangs_id)}</b><br>${empfang}` +
		(liste ? `<b>Fehlende Angaben</b><br>${liste}<br><br>` : '') + link;
}

/** Teams-Nachricht einer Freigabe-Karte (Spalte teams_nachricht: JSON { team_id, channel_id, id }). */
function teamsNachrichtLesen(wert) {
	let o = wert;
	if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { return null; } }
	if (!o || typeof o !== 'object') return null;
	const team = String(o.team_id || '').trim();
	const kanal = String(o.channel_id || '').trim();
	const id = String(o.id || '').trim();
	if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(team) || !/^19:[^\s]+@thread\.[a-z0-9]+$/i.test(kanal) || !/^\d{6,20}$/.test(id)) return null;
	return { team_id: team, channel_id: kanal, id };
}

function zeitText(iso, zeitzone) {
	const d = new Date(iso);
	if (!iso || Number.isNaN(d.getTime())) return '';
	try { return d.toLocaleString('de-DE', { timeZone: zeitzone || 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }); } catch (e) { return d.toISOString(); }
}

/** Freigabe-Karte ohne Buttons und ohne Link-Adressen (zum Speichern). Gibt null zurück, wenn ein Link übrig bliebe. */
function karteOhneLink(karte) {
	if (!karte || typeof karte !== 'object' || !Array.isArray(karte.body)) return null;
	const { actions, selectAction, ...rest } = karte;
	const k = JSON.parse(JSON.stringify(rest));
	const weg = (o) => {
		if (Array.isArray(o)) return o.forEach(weg);
		if (o && typeof o === 'object') {
			delete o.selectAction; delete o.actions;
			for (const v of Object.values(o)) weg(v);
		}
	};
	weg(k);
	return /https?:\/\/|epa-freigabe\?t=/i.test(JSON.stringify(k)) ? null : k;
}

/**
 * Warten-Karte aus der ursprünglichen Freigabe-Karte (Spalte teams_karte): alle Angaben (vorhanden, fehlt noch,
 * Hinweise) bleiben, der Kopf zeigt "Wartet auf Antwort", der Entwurf wird durch den verschickten Text ersetzt,
 * Link-Hinweis und Button entfallen. Gibt null zurück, wenn die Karte nicht lesbar ist.
 */
function karteWarten(original, f, { kopf, zeilen }) {
	let k = original;
	if (typeof k === 'string') { try { k = JSON.parse(k); } catch (e) { return null; } }
	if (!k || !Array.isArray(k.body) || !k.body.length) return null;
	const tb = (text, extra) => ({ type: 'TextBlock', text, wrap: true, ...(extra || {}) });
	const body = [];
	for (const b of k.body.slice(1)) {
		if (b && b.type === 'TextBlock' && b.isSubtle && /Link|Es wird nichts ohne Klick/.test(String(b.text || ''))) continue;
		if (b && b.type === 'TextBlock' && /Erneut zur Freigabe/.test(String(b.text || ''))) continue;
		if (b && b.type === 'Container' && Array.isArray(b.items) && /ENTWURF DER/.test(String((b.items[0] || {}).text || ''))) {
			body.push({ ...b, items: [tb('VERSCHICKTE ' + (f.art === 'erinnerung' ? 'ERINNERUNG' : 'RÜCKFRAGE'), { weight: 'Bolder', size: 'Small', isSubtle: true }), tb(String(f.entwurf_text || (b.items[1] || {}).text || '').slice(0, 800))] });
			continue;
		}
		body.push(b);
	}
	const head = { type: 'ColumnSet', columns: [
		{ type: 'Column', width: 'stretch', items: [tb(kopf, { weight: 'Bolder', size: 'Medium' })] },
		{ type: 'Column', width: 'auto', items: [tb('WARTET', { weight: 'Bolder', size: 'Small', color: 'Accent' })] },
	] };
	const info = { type: 'Container', style: 'accent', spacing: 'Medium', items: zeilen.filter(Boolean).map((t) => tb(t, { spacing: 'Small' })) };
	return { type: 'AdaptiveCard', $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', version: '1.4', body: [head, ...body.slice(0, 1), info, ...body.slice(1)] };
}

/**
 * Karte, die eine Freigabe-Karte im Kanal nach der Entscheidung ersetzt (ohne Link).
 * zustand: Status der Freigabe (gesendet, abgelehnt, fehler, ersetzt, unzustellbar) oder "erneuert" (neuer Link verschickt).
 * Gibt null zurück, wenn die Karte (noch) nicht geändert werden soll (offen, in_versand, unbekannt).
 */
function karteZustand(fg, { zustand, zeitzone, jetzt, frist, original } = {}) {
	const f = fg || {};
	const z = String(zustand || f.status || '');
	const wer = String(f.entscheider || '').trim();
	let titel; let stil; let zeilen = [];
	if (z === 'gesendet') {
		// Karte im Kanal "Warten auf Kunde": Rückfrage ist raus, Antwort steht aus.
		const manuell = f.entscheidung === 'manuell_gesendet';
		const was0 = f.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage';
		titel = '⏳ Wartet auf Antwort des Kunden';
		stil = 'accent';
		let gefragt = [];
		try { gefragt = (typeof f.fehlende_felder === 'string' ? JSON.parse(f.fehlende_felder || '[]') : (f.fehlende_felder || [])).map((x) => x.anzeigename || x.feldname).filter(Boolean); } catch (e) { gefragt = []; }
		zeilen = [
			was0 + (manuell ? ' direkt in Outlook verschickt' : f.bearbeitet ? ' bearbeitet und verschickt' : ' verschickt') + (manuell || !wer ? '' : ' von ' + wer) + ' · ' + zeitText(f.gesendet_am || jetzt, zeitzone),
			gefragt.length ? 'Gefragt: ' + gefragt.join(', ').slice(0, 300) : '',
			frist ? 'Antwort erwartet bis ' + zeitText(frist, zeitzone) : '',
		];
	} else if (z === 'abgelehnt') {
		titel = '❌ Abgelehnt'; stil = 'attention';
		zeilen = [(wer ? 'Von ' + wer + ' · ' : '') + zeitText(jetzt, zeitzone), f.grund ? 'Grund: ' + String(f.grund).slice(0, 300) : '', 'Der Vorgang liegt jetzt bei einem Mitarbeiter (Eskaliert / Manuell).'];
	} else if (z === 'fehler') {
		titel = '⚠️ Versand fehlgeschlagen'; stil = 'warning';
		zeilen = [(wer ? 'Freigegeben von ' + wer + ' · ' : '') + zeitText(jetzt, zeitzone), 'Die Mail wurde nicht gesendet. Nach Behebung kommt sie automatisch mit neuem Link erneut zur Freigabe.'];
	} else if (z === 'ersetzt') {
		titel = '↩️ Nicht mehr nötig'; stil = 'emphasis';
		zeilen = ['Der Kunde hat geantwortet, bevor die Rückfrage freigegeben wurde. Die Antwort wird verarbeitet.', zeitText(jetzt, zeitzone)];
	} else if (z === 'erneuert') {
		titel = '⏰ Dieser Link gilt nicht mehr'; stil = 'warning';
		zeilen = ['Ein neuer Freigabe-Link für diesen Vorgang steht weiter unten im Kanal.', zeitText(jetzt, zeitzone)];
	} else if (z === 'unzustellbar') {
		titel = '📭 Gesendet, aber nicht zugestellt'; stil = 'attention';
		zeilen = ['Die Mail kam beim Kunden nicht an. Siehe Meldung im Kanal „Bitte ansehen“.', zeitText(jetzt, zeitzone)];
	} else {
		return null;
	}
	const was = f.art === 'erinnerung' ? 'Erinnerung' : 'Rückfrage' + (Number(f.runde) > 0 ? ' (Runde ' + Number(f.runde) + ')' : '');
	const fakten = [{ title: 'Vorgang', value: String(f.vorgangs_id || '–') }, { title: 'Art', value: was }];
	if (f.betreff) fakten.push({ title: 'Betreff', value: String(f.betreff).slice(0, 150) });
	const tb = (text, extra) => ({ type: 'TextBlock', text, wrap: true, ...(extra || {}) });
	const karte = {
		type: 'AdaptiveCard', $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', version: '1.4',
		body: [
			{ type: 'Container', style: stil, bleed: true, items: [tb(titel, { weight: 'bolder', size: 'medium' })] },
			{ type: 'FactSet', facts: fakten, spacing: 'Medium' },
